+  display:flex; align-items:center; justify-content:space-between;
+  padding:12px 2px;
+  color:rgba(255,255,255,.92);
+  font-weight:650;
+}
+.mobile-nav a + a{border-top:1px solid rgba(255,255,255,.10)}
+
+.banner{
+  background:linear-gradient(90deg, rgba(254,172,50,.18), rgba(254,172,50,.04));
+  border-bottom:1px solid rgba(254,172,50,.28);
+  color:#fff;
+}
+.banner-inner{display:flex; align-items:center; justify-content:center; padding:10px 0}
+.banner a{color:#fff; font-weight:700}
+.banner .pill{
+  background:rgba(255,255,255,.10);
+  border:1px solid rgba(255,255,255,.14);
+  border-radius:999px;
+  padding:8px 12px;
+}
+
+/* Layout */
+main{padding:26px 0 44px}
+
+.section-head{display:flex; align-items:baseline; justify-content:space-between; gap:14px; margin:14px 0 14px}
+.section-head h2{margin:0; font-size:18px; letter-spacing:.2px}
+.section-head p{margin:0; color:var(--muted); font-size:14px}
+
+.grid{
+  display:grid;
+  grid-template-columns:repeat(12, 1fr);
+  gap:18px;
+}
+
+.featured{grid-column:1/-1}
+
+.cards{grid-column:1/-1; display:grid; grid-template-columns:repeat(12, 1fr); gap:18px}
+.cards .card{grid-column:span 4}
+
+.card{
+  background:#fff;
+  border:1px solid var(--border);
+  border-radius:var(--radius);
+  overflow:hidden;
+  box-shadow:0 0 0 rgba(0,0,0,0);
+  transition:transform .12s ease, box-shadow .12s ease;
+}
+.card:hover{transform:translateY(-2px); box-shadow:var(--shadow)}
+
+.card-media{
+  position:relative;
+  aspect-ratio:16/9;
+  overflow:hidden;
+  background:linear-gradient(135deg, rgba(10,10,35,.96), rgba(10,10,35,.78));
+}
+.card-media img{width:100%; height:100%; object-fit:cover; display:block; opacity:.92}
+
+.tag{
+  position:absolute;
+  left:14px; top:14px;
+  display:inline-flex;
+  align-items:center;
+  padding:6px 10px;
+  border-radius:999px;
+  background:rgba(254,172,50,.95);
+  color:#1a1326;
+  font-weight:800;
+  font-size:12px;
+  letter-spacing:.2px;
+  text-transform:none;
+}
+.tag[data-tone="cool"]{background:rgba(114,194,255,.92)}
+.tag[data-tone="violet"]{background:rgba(173,146,255,.92)}
+.tag[data-tone="mint"]{background:rgba(120,240,210,.92)}
+.tag[data-tone="rose"]{background:rgba(255,176,176,.92)}
+
+.card-body{padding:14px 14px 16px}
+.card-title{margin:8px 0 12px; font-size:16px; line-height:1.28; letter-spacing:.1px}
+.meta{display:flex; align-items:center; gap:10px; color:var(--muted); font-size:13px}
+.avatar{
+  width:28px; height:28px;
+  border-radius:999px;
+  background:rgba(10,10,35,.08);
+  border:1px solid rgba(10,10,35,.10);
+  overflow:hidden;
+  flex:0 0 auto;
+}
+.avatar img{width:100%; height:100%; object-fit:cover; display:block}
+.meta strong{color:var(--text); font-weight:700}
+.meta .dot{opacity:.6}
+
+.featured-card{
+  display:grid;
+  grid-template-columns:1.2fr 1fr;
+  gap:0;
+}
+.featured-card .card-media{aspect-ratio:auto; min-height:300px}
+.featured-card .card-title{font-size:22px}
+.featured-card .card-body{padding:18px 18px 18px}
+
+.actions{display:flex; justify-content:center; margin:24px 0 0}
+
+/* Learn page */
+.soft{
+  background:var(--bg-soft);
+  border:1px solid rgba(10,10,35,.08);
+  border-radius:var(--radius);
+  padding:18px;
+}
+
+.syllabus{display:grid; grid-template-columns:repeat(12,1fr); gap:14px}
