+  width:38px; height:38px; border-radius:12px;
+  background:rgba(254,172,50,.18);
+  border:1px solid rgba(254,172,50,.35);
+  display:grid; place-items:center;
+  color:var(--navy);
+}
+.path h3{margin:0; font-size:15px}
+.path p{margin:4px 0 0; color:var(--muted); font-size:13px}
+
+.two-col{display:grid; grid-template-columns:repeat(12,1fr); gap:18px}
+.two-col > *{grid-column:span 6}
+.list{margin:10px 0 0; padding:0; list-style:none}
+.list li{padding:10px 0; border-top:1px solid rgba(10,10,35,.10)}
+.list li:first-child{border-top:0}
+.list a{color:var(--link); font-weight:700}
+.kicker{color:var(--muted); font-size:13px; margin:0}
+
+/* Donate */
+.donate-hero{display:grid; grid-template-columns:repeat(12,1fr); gap:18px}
+.donate-hero .copy{grid-column:span 7}
+.donate-hero .panel{grid-column:span 5}
+.donate-hero h1{margin:0 0 10px; font-size:30px; line-height:1.12}
+.donate-hero p{margin:0; color:var(--muted)}
+
+.donation-panel{
+  background:#fff;
+  border:1px solid rgba(10,10,35,.12);
+  border-radius:var(--radius);
+  padding:16px;
+  box-shadow:var(--shadow);
+}
+.tabs{display:flex; gap:10px; flex-wrap:wrap}
+.tab{
+  border-radius:999px;
+  border:1px solid rgba(10,10,35,.16);
+  background:#fff;
+  padding:10px 12px;
+  font-weight:800;
+  cursor:pointer;
+}
+.tab[aria-selected="true"]{
+  background:rgba(254,172,50,.92);
+  border-color:rgba(0,0,0,.08);
+}
+.donation-desc{margin:12px 0 14px; color:var(--muted)}
+.donation-sub{margin:10px 0 0; color:var(--muted); font-size:13px}
+.donation-sub a{color:var(--link); font-weight:700}
+
+.bullets{margin:10px 0 0; padding-left:18px; color:var(--muted)}
+.bullets li{margin:8px 0}
+
+.stats{display:grid; grid-template-columns:repeat(12,1fr); gap:12px; margin-top:14px}
+.stat{grid-column:span 6; background:#fff; border:1px solid var(--border); border-radius:var(--radius-sm); padding:12px}
+.stat strong{display:block; font-size:18px}
+.stat span{color:var(--muted); font-size:13px}
+
+.accordion{border:1px solid var(--border); border-radius:var(--radius); overflow:hidden; background:#fff}
+.acc-item + .acc-item{border-top:1px solid rgba(10,10,35,.10)}
+.acc-btn{
+  width:100%;
+  display:flex; align-items:center; justify-content:space-between;
+  gap:14px;
+  padding:14px 14px;
+  background:#fff;
+  border:0;
+  cursor:pointer;
+  text-align:left;
+  font-weight:800;
+}
+.acc-btn span{color:var(--muted); font-weight:700; font-size:12px}
+.acc-panel{max-height:0; overflow:hidden; transition:max-height .22s ease; background:rgba(10,10,35,.02)}
+.acc-panel-inner{padding:0 14px 14px; color:var(--muted)}
+.acc-item[data-open="true"] .acc-panel{max-height:240px}
+
+/* Tag pages */
+.tag-header{display:flex; align-items:baseline; justify-content:space-between; gap:14px; padding:12px 0 10px}
+.tag-header h1{margin:0; font-size:26px; letter-spacing:.2px}
+.tag-header p{margin:0; color:var(--muted)}
+
+.pill-row{display:flex; gap:10px; overflow:auto; padding:10px 0 6px}
+.pill-tag{
+  flex:0 0 auto;
+  padding:8px 12px;
+  border-radius:999px;
+  border:1px solid rgba(10,10,35,.14);
+  background:#fff;
+  color:var(--text);
+  font-weight:750;
+  font-size:13px;
+}
+.pill-tag strong{color:var(--muted); font-weight:800}
+.pill-tag:hover{border-color:rgba(10,10,35,.22)}
+
+/* Footer */
+footer{background:var(--navy); color:rgba(255,255,255,.92)}
+.footer-inner{padding:30px 0}
+.footer-grid{display:grid; grid-template-columns:repeat(12,1fr); gap:18px}
+.footer-grid > div{grid-column:span 6}
+.footer-title{margin:0 0 10px; font-size:14px; letter-spacing:.2px}
+.footer-text{margin:0; color:rgba(255,255,255,.76)}
+.footer-links{display:flex; flex-wrap:wrap; gap:10px; margin-top:10px}
+.footer-links a{color:rgba(255,255,255,.82)}
+.footer-links a:hover{color:#fff}
+.footer-small{margin-top:16px; color:rgba(255,255,255,.62); font-size:13px}
+
+/* Responsive */
+@media (max-width: 960px){
+  .header-search{display:none}
+  .hamburger{display:inline-grid; place-items:center}
+  .nav-links{display:none}
+  .featured-card{grid-template-columns:1fr}
+  .cards .card{grid-column:span 6}
+  .donate-hero .copy, .donate-hero .panel{grid-column:1/-1}
+}
+
+@media (max-width: 680px){
+  .cards .card{grid-column:1/-1}
+  .syllabus .path{grid-column:1/-1}
+  .two-col > *{grid-column:1/-1}
+  .footer-grid > div{grid-column:1/-1}
+}
+
*** End Patch
PATCH

